render:
const { root, params, progress, time, width, height } = ctx;
const canvas = root.querySelector('#falling-text-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const lines = [
  { text: params.line1_text || "CREATIVIDAD", size: params.line1_size || 54 },
  { text: params.line2_text || "EN MOVIMIENTO", size: params.line2_size || 36 },
  { text: params.line3_text || "DIGITAL", size: params.line3_size || 48 }
];

const textColor = params.text_color || "#FFFFFF";
const dotColor = params.dot_color || "#FF3366";
const bgColor = params.bg_color || "#111116";
const gravity = (params.gravity_force || 10) * 0.1;

// Limpiar fondo
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

// Semilla pseudo-aleatoria determinista para físicas consistentes
function seededRandom(seed) {
  let x = Math.sin(seed++) * 10000;
  return x - Math.floor(x);
}

// Calcular layout global centrado
const lineSpacing = 1.35;
let totalHeight = 0;
lines.forEach(l => { totalHeight += l.size * lineSpacing; });

const startY = (height - totalHeight) / 2 + lines[0].size / 2;

// Contar caracteres totales para escalar los retrasos correctamente
let totalChars = 0;
lines.forEach(l => totalChars += l.text.length);

const chars = [];
let currentY = startY;
let seedCounter = 1;
let globalCharIndex = 0;

lines.forEach((l, lineIdx) => {
  c.font = `bold ${l.size}px system-ui, -apple-system, sans-serif`;
  let totalLineWidth = 0;
  const charWidths = [];

  for (let i = 0; i < l.text.length; i++) {
    const w = c.measureText(l.text[i]).width;
    charWidths.push(w);
    totalLineWidth += w;
  }

  let startX = (width - totalLineWidth) / 2;

  for (let i = 0; i < l.text.length; i++) {
    const ch = l.text[i];
    const w = charWidths[i];
    const targetX = startX + w / 2;
    const targetY = currentY;

    // Propiedades físicas para la caída
    const r1 = seededRandom(seedCounter++);
    const r2 = seededRandom(seedCounter++);
    const r3 = seededRandom(seedCounter++);

    const vx = (r1 - 0.5) * 14 * (1 + lineIdx * 0.2);
    const vy = -r2 * 8 - 4;
    const rotSpeed = (r3 - 0.5) * 12;
    const floorY = height - 25 - (r1 * 15);

    // Offset de entrada escalado para no sobrepasar pEnterEnd
    const enterDelay = totalChars > 1 ? (globalCharIndex / totalChars) * 0.28 : 0;
    globalCharIndex++;

    chars.push({
      char: ch,
      size: l.size,
      targetX,
      targetY,
      enterDelay,
      vx,
      vy,
      rotSpeed,
      floorY,
      lineIdx
    });

    startX += w;
  }
  currentY += l.size * lineSpacing;
});

// FASES DE TIEMPO (basado en progress 0.0 -> 1.0)
const pEnterEnd = 0.40;
const pImpact = 0.48;
const pFallStart = 0.48;

// Dibujar Letras
chars.forEach(ch => {
  if (ch.char === ' ') return;

  let x = ch.targetX;
  let y = ch.targetY;
  let alpha = 1;
  let rotation = 0;

  if (progress < pEnterEnd) {
    // Fase 1: Entrada suave de cada letra
    if (progress < ch.enterDelay) {
      alpha = 0;
      x = ch.targetX + 120;
      y = ch.targetY - 40;
    } else {
      const duration = pEnterEnd - ch.enterDelay;
      const letterP = Math.min(Math.max((progress - ch.enterDelay) / duration, 0), 1);
      const easeP = 1 - Math.pow(1 - letterP, 3); // Ease out cubic

      x = ch.targetX + (1 - easeP) * 120;
      y = ch.targetY - (1 - easeP) * 40;
      alpha = letterP;
    }
  } else if (progress >= pFallStart) {
    // Fase 3: Física de Caída por gravedad tras el impacto
    const dt = (progress - pFallStart) * 40;

    x = ch.targetX + ch.vx * dt;
    y = ch.targetY + ch.vy * dt + 0.5 * gravity * 15 * dt * dt;
    rotation = ch.rotSpeed * dt * (Math.PI / 180);

    // Colisión con el suelo
    if (y > ch.floorY) {
      y = ch.floorY;
      rotation = (ch.vx > 0 ? 0.4 : -0.4) * Math.min(1, (dt - 2));
    }
  }

  c.save();
  c.translate(x, y);
  c.rotate(rotation);
  c.font = `bold ${ch.size}px system-ui, -apple-system, sans-serif`;
  c.fillStyle = textColor;
  c.globalAlpha = Math.max(0, Math.min(1, alpha));
  c.textAlign = "center";
  c.textBaseline = "middle";
  c.fillText(ch.char, 0, 0);
  c.restore();
});

// Dibujar el Punto y Efecto de Impacto
if (progress >= 0.35) {
  const lastChar = chars[chars.length - 1];
  const endX = lastChar ? lastChar.targetX + lastChar.size * 0.6 : width / 2;
  const endY = lastChar ? lastChar.targetY : height / 2;
  const dotRadius = lines[2].size * 0.18;

  let dotX = endX;
  let dotY = endY;

  if (progress < pImpact) {
    // El punto entra volando rápido desde la derecha arriba
    const pDot = (progress - 0.35) / (pImpact - 0.35);
    const easeDot = Math.pow(pDot, 2);
    dotX = width + 50 - (width + 50 - endX) * easeDot;
    dotY = -50 + (endY + 50) * easeDot;
  } else {
    // Tras el impacto cae junto con las letras
    const dt = (progress - pImpact) * 40;
    dotX = endX + 3 * dt;
    dotY = endY + 0.5 * gravity * 18 * dt * dt;
    if (dotY > height - 20) {
      dotY = height - 20;
    }
  }

  // Dibujar punto
  c.save();
  c.fillStyle = dotColor;
  c.shadowColor = dotColor;
  c.shadowBlur = 12;
  c.beginPath();
  c.arc(dotX, dotY, dotRadius, 0, Math.PI * 2);
  c.fill();
  c.restore();

  // Onda Expansiva (Shockwave) al impactar
  if (progress >= pImpact && progress < pImpact + 0.12) {
    const shockP = (progress - pImpact) / 0.12;
    const shockRadius = shockP * 180 * (lines[2].size / 48);
    c.save();
    c.strokeStyle = dotColor;
    c.lineWidth = 4 * (1 - shockP);
    c.globalAlpha = 1 - shockP;
    c.beginPath();
    c.arc(endX, endY, shockRadius, 0, Math.PI * 2);
    c.stroke();
    c.restore();
  }
}
